class BridgeNetwork:
    def __init__(self, name):
        self.name = name
        self.dns = {}  # container name -> current IP

    def connect(self, container_name, ip):
        self.dns[container_name] = ip

    def restart_with_new_ip(self, container_name, new_ip):
        self.dns[container_name] = new_ip  # DNS updates automatically

    def resolve(self, container_name):
        return self.dns.get(container_name)


net = BridgeNetwork("myapp_default")
net.connect("db", "172.18.0.2")
net.connect("api", "172.18.0.3")

print("api connects to db at:", net.resolve("db"))

net.restart_with_new_ip("db", "172.18.0.5")
print("after restart, name still resolves:", net.resolve("db"))
